import { Box, Button, Chip, Divider, Stack, Typography } from '@mui/material';
import { graphql, navigate } from 'gatsby';
import React from 'react';
import { Item__Props } from '../components/AllItems/ItemMap';
import SoundCloudItem from '../components/AllItems/SoundCloudItem';
import Navbar from '../components/Shared/Navbar';
import Layout from 'layouts';
import Footer from '../components/Codes/Footer';

const SingleMusic = ({ data }) => {
  const { work } = data;
  const itemProps: Item__Props = {
    title: work.Title,
    snippet: '',
    id: work.id,
    category: 'music',
    date: new Date().toJSON(),
    embedLink: work.embedLink,
    image: {
      url: work.image || null,
    },
    tags: work.tags.flatMap((t) => t.tagName),
    shareLink: work.embedLink,
    detailLink: work.embedLink,
    type: work.platform,
  };
  return (
    <Layout>
      <Box>
        <Navbar />
        <Stack
          sx={{
            height: '100vh',
            width: '100%',
            maxWidth: '350px',
            margin: 'auto',
            paddingTop: '5rem',
          }}
          alignItems={'center'}
          gap={3}
        >
          {work.platform === 'soundcloud' && <SoundCloudItem {...itemProps} />}
          <Button
            onClick={() => navigate('/codes#projefts')}
            variant="contained"
            fullWidth
            sx={{ mb: 10 }}
          >
            Back To All Projects
          </Button>
        </Stack>
        <Box sx={{ marginTop: '1vh' }}>
          <Footer />
        </Box>
      </Box>
    </Layout>
  );
};
export const pageQuery = graphql`
  query Music($id: String!) {
    work: strapiMusic(id: { eq: $id }) {
      id
      Title
      platform
      link
      embedLink
      createdAt
      artwork {
        localFile {
          childImageSharp {
            gatsbyImageData
          }
        }
      }
      artist
      released(fromNow: true)
      tags {
        tagName
      }
    }
  }
`;
export default SingleMusic;
